value.command:
node --input-type=module <<'PM_RELEASE_TEST'
import assert from 'node:assert/strict';
import test from 'node:test';
import { mkdtemp, rm } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { PmClient, locateItem, readLocatedItem, readSettings } from '@unbrained/pm-cli/sdk';
import { createChangelog } from 'pm-changelog';
const source = resolve('.agents/pm');
const settings = await readSettings(source);
const located = await locateItem(source, 'pm-linear-hb2g');
assert.ok(located);
const actual = (await readLocatedItem(located, { schema: settings.schema })).document.metadata;
const scratch = await mkdtemp(join(tmpdir(), 'release-closure-'));
process.env.GIT_CEILING_DIRECTORIES = scratch;
try {
  const pm = new PmClient({ cwd: scratch, pmRoot: join(scratch, '.agents/pm'), noExtensions: true, author: 'fixture' });
  await pm.init('release-fixture');
  const created = await pm.create({ id: 'delivered', type: 'Issue', title: 'Previously shipped fix', createMode: 'progressive',
    ...(actual.release ? { release: actual.release } : {}), unset: ['parent', 'goal', 'objective', 'sprint', ...(actual.release ? [] : ['release'])] });
  await pm.close(created.item.id, 'Synthetic later closure', { force: true });
  const items = (await pm.listAllComplete()).items;
  assert.equal(items.length, 1);
  assert.equal(items[0].status, 'closed');
  const common = { items, respectItemRelease: true, includeStatuses: ['closed'], includeEmpty: true };
  test('later closure never republishes the delivered fix', () => {
    assert.equal(createChangelog({ ...common, version: '2026.11.6', since: '2026-11-05T00:00:00Z' }).itemCount, 0);
  });
  test('later closure retains the original release attribution', () => {
    assert.equal(createChangelog({ ...common, version: '2026.11.4', until: '2026-11-04T23:59:59Z' }).itemCount, 1);
  });
} finally { await rm(scratch, { recursive: true, force: true }); }

PM_RELEASE_TEST
